%pyspark

# ============================================================
# GIẢI MÃ CÁC MÃ UK QUAN TRỌNG
# ============================================================

def decode_code(column_name, mapping, default_label="Other/Unknown"):
    expression = None
    for code, label in mapping.items():
        if expression is None:
            expression = F.when(F.col(column_name) == code, F.lit(label))
        else:
            expression = expression.when(F.col(column_name) == code, F.lit(label))
    return expression.otherwise(F.lit(default_label))

severity_mapping = {1: "Fatal", 2: "Serious", 3: "Slight", -1: "Missing/Unknown"}
weather_mapping = {
    1: "Fine, no high winds", 2: "Raining, no high winds", 3: "Snowing, no high winds",
    4: "Fine with high winds", 5: "Raining with high winds", 6: "Snowing with high winds",
    7: "Fog or mist", 8: "Other", 9: "Unknown", -1: "Missing/Unknown"
}
light_mapping = {
    1: "Daylight", 4: "Darkness - lights lit", 5: "Darkness - lights unlit",
    6: "Darkness - no lighting", 7: "Darkness - lighting unknown", -1: "Missing/Unknown"
}
urban_mapping = {1: "Urban", 2: "Rural", 3: "Unallocated", -1: "Missing/Unknown"}
casualty_class_mapping = {1: "Driver or rider", 2: "Passenger", 3: "Pedestrian", -1: "Missing/Unknown"}

uk_collisions_labeled = (
    uk_collisions
    .withColumn("severity_label", decode_code("collision_severity", severity_mapping))
    .withColumn("weather_label", decode_code("weather_conditions", weather_mapping))
    .withColumn("light_label", decode_code("light_conditions", light_mapping))
    .withColumn("urban_rural_label", decode_code("urban_or_rural_area", urban_mapping))
)

uk_casualties_labeled = (
    uk_casualties
    .withColumn("casualty_severity_label", decode_code("casualty_severity", severity_mapping))
    .withColumn("casualty_class_label", decode_code("casualty_class", casualty_class_mapping))
)

uk_vehicles_labeled = (
    uk_vehicles
    .withColumn(
        "vehicle_group",
        F.when(F.col("vehicle_type") == 1, "Pedal cycle")
         .when(F.col("vehicle_type").isin(2, 3, 4, 5, 23, 97), "Motorcycle")
         .when(F.col("vehicle_type") == 9, "Car")
         .when(F.col("vehicle_type") == 8, "Taxi or private hire")
         .when(F.col("vehicle_type") == 11, "Bus or coach")
         .when(F.col("vehicle_type") == 19, "Van or goods vehicle <= 3.5t")
         .when(F.col("vehicle_type").isin(20, 21, 98), "Heavy goods vehicle")
         .when(F.col("vehicle_type").isin(-1, 99), "Missing/Unknown")
         .otherwise("Other vehicle")
    )
)

print("Đã tạo các bảng UK có nhãn.")

%pyspark

# ============================================================
# GIẢI PHÓNG BỘ NHỚ SAU PHẦN US ACCIDENTS
# ============================================================

# Tách các bảng tổng hợp nhỏ khỏi lineage của file US 3 GB.
us_small_summary_names = [
    "us_sampling_overview_df", "us_sample_validation_df", "us_missing_df",
    "us_severity_df", "us_severity_group_df", "us_year_df", "us_hour_df",
    "us_state_df", "us_city_df", "us_source_high_impact_df",
    "us_source_year_df", "us_weather_high_impact_df",
    "us_sun_high_impact_df", "us_infra_effect_df"
]

for dataframe_name in us_small_summary_names:
    dataframe = globals().get(dataframe_name)
    if dataframe is not None:
        try:
            globals()[dataframe_name] = detach_small_df(dataframe)
            print("Đã tách bảng tổng hợp:", dataframe_name)
        except Exception as detach_error:
            print("Không thể tách", dataframe_name, ":", detach_error)

# Bỏ toàn bộ cache của các DataFrame US rộng.
for dataframe_name in [
    "us_scope", "us_scope_with_stratum", "us_analysis_base",
    "us_analysis_clean", "us_enriched", "us_analysis"
]:
    dataframe = globals().get(dataframe_name)
    if dataframe is not None:
        try:
            dataframe.unpersist()
            print("Đã unpersist:", dataframe_name)
        except Exception:
            pass

try:
    spark.catalog.clearCache()
except Exception:
    try:
        sqlContext.clearCache()
    except Exception:
        pass

request_jvm_gc()
print("Đã giải phóng cache US; có thể tiếp tục phần Addis/ML.")
